[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --white: #ffffff;
      --purple: #7638FA;
      --orange: #FF7A00;
      --magenta: #E040A0;
      --gray-50: #FAFAFA;
      --gray-100: #F5F5F5;
      --gray-200: #E5E5E5;
      --gray-300: #D4D4D4;
      --gray-400: #A3A3A3;
      --gray-500: #737373;
      --gray-600: #525252;
      --gray-700: #404040;
      --gray-800: #262626;
      --gray-900: #171717;
      --gradient-brand: linear-gradient(135deg, #7638FA 0%, #E040A0 50%, #FF7A00 100%);
      --gradient-hero: linear-gradient(135deg, #7638FA 0%, #C040D0 35%, #E040A0 65%, #FF7A00 100%);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
      --transition: 0.2s ease;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--gray-900);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }
    ul { list-style: none; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ======= HEADER ======= */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: background var(--transition);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--black);
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--gradient-brand);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 22px; height: 22px; }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-desktop a {
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-600);
      transition: color var(--transition);
    }

    .nav-desktop a:hover { color: var(--black); }

    .btn-login {
      padding: 8px 20px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--white);
      background: var(--black);
      border-radius: var(--radius-full);
      transition: opacity var(--transition);
    }

    .btn-login:hover { opacity: 0.85; }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 28px;
      padding: 4px 0;
      z-index: 1001;
    }

    .hamburger span {
      display: block;
      width: 100%;
      height: 2.5px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 0.3s ease, opacity 0.3s ease;
    }

    .hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 999;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 32px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s ease;
    }

    .mobile-nav.open { opacity: 1; pointer-events: all; }

    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--gray-900);
      transition: color var(--transition);
    }

    .mobile-nav a:hover { color: var(--purple); }

    .mobile-nav .btn-login {
      font-size: 1.1rem;
      padding: 12px 32px;
    }

    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .hamburger { display: flex; }
      .mobile-nav { display: flex; }
    }

    /* ======= HERO ======= */
    .hero {
      position: relative;
      padding: 160px 0 100px;
      overflow: hidden;
      background: var(--gray-50);
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -40%;
      right: -20%;
      width: 700px;
      height: 700px;
      background: radial-gradient(circle, rgba(118,56,250,0.12) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(255,122,0,0.10) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 780px;
      margin: 0 auto;
      text-align: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 16px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--purple);
      margin-bottom: 28px;
    }

    .hero-badge-dot {
      width: 6px;
      height: 6px;
      background: var(--purple);
      border-radius: 50%;
      animation: pulse-dot 2s infinite;
    }

    @keyframes pulse-dot {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .hero h1 {
      font-size: 3.5rem;
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
      color: var(--black);
    }

    .hero h1 .gradient-text {
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 1.15rem;
      color: var(--gray-500);
      max-width: 560px;
      margin: 0 auto 36px;
      line-height: 1.7;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 32px;
      font-size: 1rem;
      font-weight: 700;
      color: var(--white);
      background: var(--gradient-brand);
      border-radius: var(--radius-full);
      box-shadow: 0 4px 20px rgba(118,56,250,0.35);
      transition: transform var(--transition), box-shadow var(--transition);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 28px rgba(118,56,250,0.45);
    }

    .btn-primary svg {
      width: 18px;
      height: 18px;
      transition: transform var(--transition);
    }

    .btn-primary:hover svg { transform: translateX(3px); }

    @media (max-width: 768px) {
      .hero { padding: 120px 0 72px; }
      .hero h1 { font-size: 2.25rem; }
      .hero p { font-size: 1rem; }
    }

    /* ======= SECTIONS SHARED ======= */
    .section { padding: 100px 0; }
    .section-alt { background: var(--gray-50); }

    .section-header {
      margin-bottom: 48px;
    }

    .section-label {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 12px;
    }

    .section-title {
      font-size: 2.5rem;
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--black);
    }

    @media (max-width: 768px) {
      .section { padding: 72px 0; }
      .section-title { font-size: 1.75rem; }
    }

    /* ======= FEATURE / SAFETY / CREATORS CARDS ======= */
    .content-card {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .content-card-reverse { direction: rtl; }
    .content-card-reverse > * { direction: ltr; }

    .content-card-visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
    }

    .content-card-visual-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .visual-features {
      background: linear-gradient(135deg, #7638FA 0%, #9B59FA 100%);
    }

    .visual-safety {
      background: linear-gradient(135deg, #E8F5E9 0%, #C8E6C9 50%, #A5D6A7 100%);
    }

    .visual-creators {
      background: linear-gradient(135deg, #FF7A00 0%, #FF9F45 100%);
    }

    .visual-icon {
      width: 80px;
      height: 80px;
      background: rgba(255,255,255,0.2);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .visual-icon svg {
      width: 40px;
      height: 40px;
      color: var(--white);
      stroke: var(--white);
      fill: none;
    }

    .visual-safety .visual-icon { background: rgba(0,0,0,0.08); }
    .visual-safety .visual-icon svg { stroke: var(--gray-800); }

    .content-card-body h2 {
      font-size: 2rem;
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
    }

    .content-card-body p {
      font-size: 1rem;
      color: var(--gray-500);
      line-height: 1.7;
      margin-bottom: 24px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--purple);
      transition: gap var(--transition);
    }

    .link-arrow:hover { gap: 10px; }

    .link-arrow.orange { color: var(--orange); }

    .link-arrow svg { width: 16px; height: 16px; }

    @media (max-width: 768px) {
      .content-card {
        grid-template-columns: 1fr;
        gap: 32px;
      }
      .content-card-reverse { direction: ltr; }
      .content-card-body h2 { font-size: 1.5rem; }
    }

    /* ======= TAGLINE BANNER ======= */
    .tagline-banner {
      padding: 80px 0;
      background: var(--black);
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--gradient-hero);
      opacity: 0.12;
      pointer-events: none;
    }

    .tagline-banner h2 {
      position: relative;
      z-index: 1;
      font-size: 3rem;
      font-weight: 800;
      text-align: center;
      color: var(--white);
      letter-spacing: -0.02em;
      max-width: 700px;
      margin: 0 auto;
    }

    @media (max-width: 768px) {
      .tagline-banner { padding: 56px 0; }
      .tagline-banner h2 { font-size: 1.75rem; }
    }

    /* ======= NEWS CAROUSEL ======= */
    .news-section { padding: 100px 0; }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
    }

    .news-header .link-arrow { font-size: 0.9rem; }

    .news-carousel-wrapper {
      position: relative;
    }

    .news-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 8px;
    }

    .news-carousel::-webkit-scrollbar { display: none; }

    .news-card {
      flex: 0 0 320px;
      scroll-snap-align: start;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: var(--white);
      border: 1px solid var(--gray-200);
      transition: box-shadow var(--transition), transform var(--transition);
      cursor: pointer;
    }

    .news-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-4px);
    }

    .news-card-thumb {
      height: 180px;
      position: relative;
      overflow: hidden;
    }

    .news-card-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .thumb-1 { background: linear-gradient(135deg, #7638FA 0%, #C040D0 100%); }
    .thumb-2 { background: linear-gradient(135deg, #FF7A00 0%, #FFB347 100%); }
    .thumb-3 { background: linear-gradient(135deg, #E040A0 0%, #7638FA 100%); }
    .thumb-4 { background: linear-gradient(135deg, #00C9A7 0%, #7638FA 100%); }

    .thumb-icon {
      width: 56px;
      height: 56px;
      background: rgba(255,255,255,0.2);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .thumb-icon svg {
      width: 28px;
      height: 28px;
      stroke: white;
      fill: none;
    }

    .news-card-body { padding: 20px; }

    .news-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 12px;
    }

    .news-tag {
      display: inline-block;
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      padding: 4px 10px;
      border-radius: var(--radius-full);
      background: var(--gray-100);
      color: var(--gray-600);
    }

    .news-tag.announcements {
      background: rgba(118,56,250,0.1);
      color: var(--purple);
    }

    .news-tag.product {
      background: rgba(255,122,0,0.1);
      color: var(--orange);
    }

    .news-tag.tips {
      background: rgba(224,64,160,0.1);
      color: var(--magenta);
    }

    .news-tag.safety {
      background: rgba(0,201,167,0.1);
      color: #00A88A;
    }

    .news-card-title {
      font-size: 0.95rem;
      font-weight: 700;
      line-height: 1.4;
      color: var(--gray-900);
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-date {
      font-size: 0.8rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    @media (max-width: 768px) {
      .news-section { padding: 72px 0; }
